"use client"

/**
 * Clean-room company toolbar. Behavior is inspired by an unlicensed reference.
 * No source, class names, copy, or assets were copied.
 * filter-toolbar is the single-value chip bar. This one is multi-select facets.
 */

import * as React from "react"
import { SlidersHorizontal } from "lucide-react"

import { cn } from "@/lib/utils"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet"
import { facetSelectionCount, toggleFacetValue, type CrmFacetSelection } from "@/lib/crm-companies"
import { SearchField } from "@/components/ui/search-field"
import { SegmentedControl, type Segment } from "@/components/ui/segmented-control"

export type CrmToolbarFacet = {
  id: string
  label: string
  options: readonly { value: string; label: string }[]
}

export type CrmToolbarLabels = {
  search?: string
  searchPlaceholder?: string
  segments?: string
  filters?: string
  filterMenu?: string
  openFilters?: string
  filterDescription?: string
  clear?: string
  emptyFacets?: string
}

export type CrmToolbarProps = {
  query: string
  onQueryChange: (query: string) => void
  segment: string
  onSegmentChange: (segment: string) => void
  segments?: readonly Segment[]
  facets?: readonly CrmToolbarFacet[]
  selection?: CrmFacetSelection
  onSelectionChange?: (selection: CrmFacetSelection) => void
  /** auto measures the toolbar. menu and sheet force a layout, including tests. */
  layout?: "auto" | "menu" | "sheet"
  labels?: CrmToolbarLabels
  className?: string
}

const DEFAULT_SEGMENTS: Segment[] = [
  { value: "all", label: "All" },
  { value: "active", label: "Active" },
  { value: "lead", label: "Lead" },
  { value: "churned", label: "Churned" },
]

function FacetChoices({
  facets,
  selection,
  onToggle,
}: {
  facets: readonly CrmToolbarFacet[]
  selection: CrmFacetSelection
  onToggle: (facetId: string, value: string) => void
}) {
  return (
    <div className="flex flex-col gap-4">
      {facets.map((facet) => (
        <fieldset key={facet.id} className="flex min-w-0 flex-col gap-2">
          <legend className="text-sm font-medium">{facet.label}</legend>
          {facet.options.map((option) => {
            const checked = (selection[facet.id] ?? []).includes(option.value)
            const id = `${facet.id}-${option.value}`
            return (
              <label key={option.value} htmlFor={id} className="flex min-w-0 items-center gap-2 text-sm">
                <Checkbox id={id} checked={checked} onCheckedChange={() => onToggle(facet.id, option.value)} />
                <span className="min-w-0 truncate">{option.label}</span>
              </label>
            )
          })}
        </fieldset>
      ))}
    </div>
  )
}

export function CrmToolbar({
  query,
  onQueryChange,
  segment,
  onSegmentChange,
  segments = DEFAULT_SEGMENTS,
  facets = [],
  selection = {},
  onSelectionChange,
  layout = "auto",
  labels,
  className,
}: CrmToolbarProps) {
  const rootRef = React.useRef<HTMLDivElement>(null)
  const [measuredSheet, setMeasuredSheet] = React.useState(false)
  const [sheetOpen, setSheetOpen] = React.useState(false)
  const copy = {
    search: labels?.search ?? "Search companies",
    searchPlaceholder: labels?.searchPlaceholder ?? "Search companies",
    segments: labels?.segments ?? "Segments",
    filters: labels?.filters ?? "Filters",
    filterMenu: labels?.filterMenu ?? "Filter menu",
    openFilters: labels?.openFilters ?? "Open filters",
    filterDescription: labels?.filterDescription ?? "Choose any values. A company must match every facet you set.",
    clear: labels?.clear ?? "Clear filters",
    emptyFacets: labels?.emptyFacets ?? "No filters",
  }
  const count = facetSelectionCount(selection)
  const sheet = layout === "sheet" || (layout === "auto" && measuredSheet)

  React.useLayoutEffect(() => {
    if (layout !== "auto") return
    const node = rootRef.current
    if (!node || typeof ResizeObserver === "undefined") return
    const update = (width: number) => {
      if (width > 0) setMeasuredSheet(width < 640)
    }
    update(node.getBoundingClientRect().width)
    const observer = new ResizeObserver(([entry]) => update(entry.contentRect.width))
    observer.observe(node)
    return () => observer.disconnect()
  }, [layout])

  function toggle(facetId: string, value: string) {
    onSelectionChange?.(toggleFacetValue(selection, facetId, value))
  }

  function clear() {
    onSelectionChange?.({})
  }

  const filterButton = (
    <>
      <SlidersHorizontal data-icon="inline-start" aria-hidden="true" />
      {copy.filters}
      {count > 0 ? <Badge variant="secondary">{count}</Badge> : null}
    </>
  )

  return (
    <div ref={rootRef} data-slot="crm-toolbar" className={cn("flex min-w-0 flex-col gap-3", className)}>
      <div className="flex min-w-0 flex-wrap items-center gap-2">
        <SearchField
          label={copy.search}
          placeholder={copy.searchPlaceholder}
          value={query}
          onValueChange={onQueryChange}
          className="min-w-0 flex-1 basis-48"
          classNames={{ label: "sr-only" }}
        />
        {facets.length > 0 && !sheet ? (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button type="button" variant="outline" aria-label={copy.filterMenu}>
                {filterButton}
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="max-h-80 w-64 overflow-y-auto">
              {facets.map((facet, index) => (
                <DropdownMenuGroup key={facet.id}>
                  {index > 0 ? <DropdownMenuSeparator /> : null}
                  <DropdownMenuLabel>{facet.label}</DropdownMenuLabel>
                  {facet.options.map((option) => (
                    <DropdownMenuCheckboxItem
                      key={option.value}
                      checked={(selection[facet.id] ?? []).includes(option.value)}
                      onCheckedChange={() => toggle(facet.id, option.value)}
                      onSelect={(event) => event.preventDefault()}
                    >
                      {option.label}
                    </DropdownMenuCheckboxItem>
                  ))}
                </DropdownMenuGroup>
              ))}
              {count > 0 ? (
                <>
                  <DropdownMenuSeparator />
                  <DropdownMenuGroup>
                    <DropdownMenuItem onSelect={clear}>{copy.clear}</DropdownMenuItem>
                  </DropdownMenuGroup>
                </>
              ) : null}
            </DropdownMenuContent>
          </DropdownMenu>
        ) : null}
        {facets.length > 0 && sheet ? (
          <Sheet open={sheetOpen} onOpenChange={setSheetOpen}>
            <SheetTrigger asChild>
              <Button type="button" variant="outline" aria-label={copy.openFilters}>
                {filterButton}
              </Button>
            </SheetTrigger>
            <SheetContent className="w-full sm:max-w-sm">
              <SheetHeader>
                <SheetTitle>{copy.filters}</SheetTitle>
                <SheetDescription>{copy.filterDescription}</SheetDescription>
              </SheetHeader>
              <div className="min-h-0 flex-1 overflow-y-auto px-4">
                {facets.some((facet) => facet.options.length > 0) ? (
                  <FacetChoices facets={facets} selection={selection} onToggle={toggle} />
                ) : (
                  <p className="text-sm text-muted-foreground">{copy.emptyFacets}</p>
                )}
              </div>
              <SheetFooter>
                <Button type="button" variant="outline" onClick={clear} disabled={count === 0}>
                  {copy.clear}
                </Button>
              </SheetFooter>
            </SheetContent>
          </Sheet>
        ) : null}
      </div>
      <div className="min-w-0 overflow-hidden">
        <SegmentedControl label={copy.segments} options={[...segments]} value={segment} onValueChange={onSegmentChange} />
      </div>
    </div>
  )
}

/**
 * Clean-room sales CRM model. Behavior is inspired by an unlicensed reference.
 * No source, class names, copy, sample rows, or assets were copied.
 */

export type CrmStatusTone = "neutral" | "emphasis" | "muted" | "danger"

export type CrmCompany = {
  id: string
  name: string
  logoUrl?: string
  status: string
  statusLabel: string
  statusTone?: CrmStatusTone
  owner: string
  ownerId?: string
  pipelineValue: number
  /** 0–100. */
  score: number
  /** Oldest to newest. The table draws this as a sparkline. */
  activity: readonly number[]
  activityLabel: string
  industry?: string
  region?: string
  email?: string
  website?: string
  phone?: string
  notes?: string
  /** Oldest to newest. The detail panel draws this as a trend. */
  trend?: readonly { key: string; label: string; value: number }[]
  /** 0–100 health for the meter. Falls back to score. */
  health?: number
}

export type CrmNotice = {
  id: string
  title: string
  description?: string
  time: string
  dateTime?: string
  read?: boolean
  companyId?: string
}

export type CrmSortKey = "name" | "status" | "owner" | "pipeline" | "score" | "activity"

export type CrmSort = {
  key: CrmSortKey
  direction: "asc" | "desc"
}

export type CrmFacetSelection = Record<string, readonly string[]>

export type CrmCompanyQuery = {
  search?: string
  /** Status id, or the all-segment id. */
  segment?: string
  allSegment?: string
  facets?: CrmFacetSelection
}

export type CrmCsvLabels = {
  name: string
  status: string
  owner: string
  pipeline: string
  score: string
  activity: string
}

export type CrmCompanyDraft = {
  name: string
  status: string
  ownerId: string
  email: string
  website: string
  industry: string
  region: string
  pipelineValue: string
  notes: string
  logo?: { type: string; size: number } | null
}

export type CrmDraftIssue =
  | "name-required"
  | "status-required"
  | "owner-required"
  | "email-invalid"
  | "website-invalid"
  | "pipeline-invalid"
  | "logo-type"
  | "logo-size"

export const CRM_LOGO_TYPES = ["image/png", "image/jpeg", "image/webp", "image/gif"] as const
export const CRM_LOGO_MAX_BYTES = 2_000_000

export const EMPTY_COMPANY_DRAFT: CrmCompanyDraft = {
  name: "",
  status: "",
  ownerId: "",
  email: "",
  website: "",
  industry: "",
  region: "",
  pipelineValue: "",
  notes: "",
  logo: null,
}

export function crmInitials(name: string) {
  const parts = name.split(/\s+/).filter(Boolean).slice(0, 2)
  const letters = parts.map((part) => [...part][0] ?? "").join("")
  return letters.toLocaleUpperCase() || "?"
}

export function companyFacetValue(company: CrmCompany, facetId: string) {
  if (facetId === "owner") return company.ownerId ?? company.owner
  if (facetId === "industry") return company.industry ?? ""
  if (facetId === "region") return company.region ?? ""
  if (facetId === "status") return company.status
  return ""
}

export function companySearchText(company: CrmCompany) {
  return [company.name, company.owner, company.statusLabel, company.industry, company.region, company.email]
    .filter(Boolean)
    .join(" ")
    .toLocaleLowerCase()
}

export function facetSelectionCount(selection: CrmFacetSelection) {
  return Object.values(selection).reduce((sum, values) => sum + values.length, 0)
}

export function toggleFacetValue(selection: CrmFacetSelection, facetId: string, value: string): CrmFacetSelection {
  const current = selection[facetId] ?? []
  const next = current.includes(value) ? current.filter((item) => item !== value) : [...current, value]
  return { ...selection, [facetId]: next }
}

export function filterCompanies(rows: readonly CrmCompany[], query: CrmCompanyQuery = {}) {
  const search = query.search?.trim().toLocaleLowerCase() ?? ""
  const allSegment = query.allSegment ?? "all"
  const segment = query.segment && query.segment !== allSegment ? query.segment : ""
  const facets = Object.entries(query.facets ?? {}).filter(([, values]) => values.length > 0)

  return rows.filter((company) => {
    if (segment && company.status !== segment) return false
    if (search && !companySearchText(company).includes(search)) return false
    return facets.every(([facetId, values]) => values.includes(companyFacetValue(company, facetId)))
  })
}

function sortValue(company: CrmCompany, key: CrmSortKey) {
  switch (key) {
    case "name":
      return company.name
    case "status":
      return company.statusLabel
    case "owner":
      return company.owner
    case "pipeline":
      return company.pipelineValue
    case "score":
      return company.score
    case "activity":
      return company.activity.at(-1) ?? 0
    default: {
      const unreachable: never = key
      return unreachable
    }
  }
}

export function sortCompanies(rows: readonly CrmCompany[], sort: CrmSort) {
  const direction = sort.direction === "asc" ? 1 : -1
  return [...rows].sort((a, b) => {
    const left = sortValue(a, sort.key)
    const right = sortValue(b, sort.key)
    const compared =
      typeof left === "number" && typeof right === "number"
        ? left - right
        : String(left).localeCompare(String(right), undefined, { numeric: true, sensitivity: "base" })
    if (compared !== 0) return compared * direction
    return a.id.localeCompare(b.id)
  })
}

export function paginate<T>(rows: readonly T[], page: number, pageSize: number) {
  const size = Math.max(1, Math.floor(pageSize) || 1)
  const total = rows.length
  const pages = Math.max(1, Math.ceil(total / size))
  const index = Math.min(Math.max(0, Math.floor(page) || 0), pages - 1)
  const start = index * size
  return {
    page: index,
    pages,
    start,
    end: Math.min(total, start + size),
    total,
    rows: rows.slice(start, start + size),
  }
}

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
const WEBSITE = /^https?:\/\/\S+$/i

export function companyDraftIssues(draft: CrmCompanyDraft): CrmDraftIssue[] {
  const issues: CrmDraftIssue[] = []
  if (!draft.name.trim()) issues.push("name-required")
  if (!draft.status) issues.push("status-required")
  if (!draft.ownerId) issues.push("owner-required")
  if (draft.email.trim() && !EMAIL.test(draft.email.trim())) issues.push("email-invalid")
  if (draft.website.trim() && !WEBSITE.test(draft.website.trim())) issues.push("website-invalid")
  const pipeline = Number(draft.pipelineValue)
  if (draft.pipelineValue.trim() === "" || !Number.isFinite(pipeline) || pipeline < 0) issues.push("pipeline-invalid")
  if (draft.logo && draft.logo.size > 0) {
    if (!CRM_LOGO_TYPES.includes(draft.logo.type as (typeof CRM_LOGO_TYPES)[number])) issues.push("logo-type")
    if (draft.logo.size > CRM_LOGO_MAX_BYTES) issues.push("logo-size")
  }
  return issues
}

export function companyFromDraft(
  draft: CrmCompanyDraft & { logoUrl?: string },
  context: {
    id: string
    ownerName: string
    statusLabel: string
    statusTone?: CrmStatusTone
    activityLabel: string
  },
): CrmCompany {
  const pipelineValue = Number(draft.pipelineValue)
  return {
    id: context.id,
    name: draft.name.trim(),
    logoUrl: draft.logoUrl,
    status: draft.status,
    statusLabel: context.statusLabel,
    statusTone: context.statusTone,
    owner: context.ownerName,
    ownerId: draft.ownerId,
    pipelineValue: Number.isFinite(pipelineValue) ? pipelineValue : 0,
    score: 50,
    health: 50,
    activity: [2, 2, 3, 3],
    activityLabel: context.activityLabel,
    industry: draft.industry.trim() || undefined,
    region: draft.region.trim() || undefined,
    email: draft.email.trim() || undefined,
    website: draft.website.trim() || undefined,
    notes: draft.notes.trim() || undefined,
    trend: [{ key: "now", label: context.activityLabel, value: 1 }],
  }
}

"use client"

/** Adapted from Arc UI (MIT). */

import * as React from "react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"
import { Search, X } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"

export type SearchFieldClassNames = {
  root?: string
  label?: string
  shell?: string
  input?: string
  clear?: string
}

export type SearchFieldProps = Omit<React.ComponentProps<"input">, "type" | "value" | "onChange"> & {
  label: string
  value: string
  onValueChange: (value: string) => void
  classNames?: SearchFieldClassNames
}

export const SearchField = React.forwardRef<HTMLInputElement, SearchFieldProps>(function SearchField(
  { label, value, onValueChange, id, className, classNames, ...props },
  ref,
) {
  const generated = React.useId()
  const controlId = id ?? generated
  const reduced = useReducedMotion()
  const inputRef = React.useRef<HTMLInputElement | null>(null)

  const setRefs = (node: HTMLInputElement | null) => {
    inputRef.current = node
    if (typeof ref === "function") ref(node)
    else if (ref) ref.current = node
  }

  function clear() {
    onValueChange("")
    inputRef.current?.focus()
  }

  return (
    <div data-slot="search-field" className={cn("grid min-w-0 gap-2", className, classNames?.root)}>
      <label htmlFor={controlId} data-slot="search-field-label" className={cn("text-sm font-medium", classNames?.label)}>
        {label}
      </label>
      <div
        data-slot="search-field-shell"
        data-filled={value ? "true" : undefined}
        className={cn(
          "flex h-9 min-w-0 items-center gap-1 rounded-lg border border-input bg-transparent pr-1 pl-2.5 focus-within:border-ring focus-within:ring-3 focus-within:ring-ring/50",
          classNames?.shell,
        )}
      >
        <Search className="size-4 shrink-0 text-muted-foreground" aria-hidden="true" />
        <Input
          {...props}
          ref={setRefs}
          id={controlId}
          type="search"
          value={value}
          onChange={(event) => onValueChange(event.target.value)}
          className={cn(
            "h-8 border-0 bg-transparent px-1 shadow-none focus-visible:ring-0 dark:bg-transparent [&::-webkit-search-cancel-button]:appearance-none",
            classNames?.input,
          )}
        />
        <span className="grid size-6 shrink-0 place-items-center">
          <AnimatePresence initial={false}>
            {value ? (
              <motion.span
                key="clear"
                initial={reduced ? { opacity: 0 } : { opacity: 0, scale: 0.8 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={reduced ? { opacity: 0, transition: { duration: 0 } } : { opacity: 0, scale: 0.8 }}
                transition={reduced ? { duration: motionPresets.duration.instant } : motionPresets.spring.snappy}
              >
                <Button
                  type="button"
                  variant="ghost"
                  size="icon-xs"
                  data-slot="search-field-clear"
                  className={classNames?.clear}
                  aria-label="Clear search"
                  onClick={clear}
                >
                  <X aria-hidden="true" />
                </Button>
              </motion.span>
            ) : null}
          </AnimatePresence>
        </span>
      </div>
    </div>
  )
})

"use client"

/** Adapted from Arc UI (MIT). */

import * as React from "react"
import { LayoutGroup, motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"

export type Segment = {
  value: string
  label: string
  accessory?: React.ReactNode
}

export type SegmentedControlClassNames = {
  root?: string
  track?: string
  option?: string
  selection?: string
  label?: string
}

export type SegmentedControlProps = {
  options: Segment[]
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  label?: string
  onOptionIntent?: (value: string) => void
  className?: string
  classNames?: SegmentedControlClassNames
}

export function SegmentedControl({
  options,
  value,
  defaultValue,
  onValueChange,
  label,
  onOptionIntent,
  className,
  classNames,
}: SegmentedControlProps) {
  const id = React.useId()
  const reduced = useReducedMotion()
  const track = React.useRef<HTMLDivElement>(null)
  const [internal, setInternal] = React.useState(defaultValue ?? options[0]?.value ?? "")
  const selected = value ?? internal

  React.useLayoutEffect(() => {
    const node = track.current
    if (!node) return
    const edges = () => {
      const rest = node.scrollWidth - node.clientWidth - node.scrollLeft
      node.toggleAttribute("data-fade-start", node.scrollLeft > 1)
      node.toggleAttribute("data-fade-end", rest > 1)
    }
    edges()
    node.addEventListener("scroll", edges, { passive: true })
    const observer = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(edges)
    observer?.observe(node)
    return () => {
      node.removeEventListener("scroll", edges)
      observer?.disconnect()
    }
  }, [options.length])

  const first = React.useRef(true)
  React.useEffect(() => {
    const node = track.current
    const button = node?.querySelector<HTMLElement>('[aria-pressed="true"]')
    if (!node || !button || node.scrollWidth <= node.clientWidth) {
      first.current = false
      return
    }
    const room = 20
    const start = button.offsetLeft - room
    const end = button.offsetLeft + button.offsetWidth + room - node.clientWidth
    const left = node.scrollLeft > start ? start : node.scrollLeft < end ? end : node.scrollLeft
    if (left !== node.scrollLeft) node.scrollTo({ left: Math.max(0, left), behavior: first.current || reduced ? "auto" : "smooth" })
    first.current = false
  }, [selected, reduced])

  const selectedIndex = Math.max(0, options.findIndex((option) => option.value === selected))

  function change(next: string) {
    if (value === undefined) setInternal(next)
    onValueChange?.(next)
  }

  function onKeyDown(event: React.KeyboardEvent<HTMLButtonElement>) {
    const last = options.length - 1
    const target =
      event.key === "ArrowRight" || event.key === "ArrowDown"
        ? selectedIndex === last
          ? 0
          : selectedIndex + 1
        : event.key === "ArrowLeft" || event.key === "ArrowUp"
          ? selectedIndex === 0
            ? last
            : selectedIndex - 1
          : event.key === "Home"
            ? 0
            : event.key === "End"
              ? last
              : -1
    if (target < 0 || !options[target]) return
    event.preventDefault()
    change(options[target].value)
    track.current?.querySelector<HTMLElement>(`[data-value="${CSS.escape(options[target].value)}"]`)?.focus({ preventScroll: true })
  }

  return (
    <div
      data-slot="segmented-control"
      className={cn("inline-flex min-w-0 max-w-full shrink", className, classNames?.root)}
      role="group"
      aria-label={label}
    >
      <LayoutGroup id={id}>
        <motion.div
          ref={track}
          layoutScroll
          data-slot="segmented-control-track"
          className={cn(
            "flex min-w-0 gap-0.5 overflow-x-auto rounded-lg bg-muted p-0.5 [scrollbar-width:none]",
            classNames?.track,
          )}
        >
          {options.map((option, index) => {
            const pressed = selected === option.value
            return (
              <button
                key={option.value}
                id={`${id}-${option.value}`}
                type="button"
                data-slot="segmented-control-option"
                data-value={option.value}
                className={cn(
                  "relative min-h-8 shrink-0 cursor-pointer rounded-md border-0 bg-transparent px-3 text-sm font-medium whitespace-nowrap text-muted-foreground transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none aria-pressed:text-foreground",
                  classNames?.option,
                )}
                aria-pressed={pressed}
                tabIndex={index === selectedIndex ? 0 : -1}
                onClick={() => change(option.value)}
                onKeyDown={onKeyDown}
                onPointerEnter={onOptionIntent ? () => onOptionIntent(option.value) : undefined}
                onFocus={onOptionIntent ? () => onOptionIntent(option.value) : undefined}
              >
                {pressed ? (
                  <motion.span
                    data-slot="segmented-control-selection"
                    className={cn("absolute inset-0 z-0 rounded-md border border-border bg-background shadow-sm", classNames?.selection)}
                    layoutId="selection"
                    layoutDependency={selected}
                    transition={reduced ? { duration: 0 } : motionPresets.spring.morph}
                    aria-hidden="true"
                  />
                ) : null}
                <span data-slot="segmented-control-label" className={cn("relative z-10 inline-flex items-center gap-1.5", classNames?.label)}>
                  {option.label}
                  {option.accessory}
                </span>
              </button>
            )
          })}
        </motion.div>
      </LayoutGroup>
    </div>
  )
}

